        </form>
        <?php if ($requests): ?><div class="table-wrapper"><table><thead><tr><th>Solicitud</th><th>Estudiante / RU</th><th>Carrera</th><th>Modalidad</th><th>Enviada</th><th>Estado</th><th>Habilitación</th><th>Detalle</th></tr></thead><tbody>
            <?php foreach ($requests as $request): ?><tr><td>#<?= (int) $request['id_solicitud'] ?></td><td><?= e($request['estudiante']) ?><br><small><?= e($request['registro_universitario'] ?? 'Sin RU') ?></small></td><td><?= e($request['nombre_carrera']) ?></td><td><?= e($request['modalidad']) ?></td><td><?= e($request['enviado_en'] ?? '—') ?></td><td><?= e($request['estado']) ?></td><td><?= $request['habilitado_en'] ? e($request['habilitado_en']) : '—' ?></td><td><a class="btn btn-sm btn-outline-primary" href="<?= e(app_url('modalidades-grado/solicitudes.php?id=' . (int) $request['id_solicitud'] . '&estado=' . rawurlencode($state))) ?>">Revisar</a></td></tr><?php endforeach; ?>
        </tbody></table></div><?php else: ?><p class="form-hint">No hay solicitudes para este filtro.</p><?php endif; ?>
