        <?php if ($selectedRequest['estado'] === 'enviada'): ?>
            <section class="card mg-panel"><h3>Iniciar revisión</h3><form method="post" action="<?= e(app_url('modalidades-grado/solicitudes.php?id=' . $requestId . '&estado=' . rawurlencode($state))) ?>"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id_solicitud" value="<?= $requestId ?>"><label>Nota interna (opcional)<textarea class="form-control" name="observacion" rows="2" maxlength="5000"></textarea></label><button class="btn btn-primary" name="accion" value="iniciar_revision">Iniciar revisión</button></form></section>
        <?php elseif ($selectedRequest['estado'] === 'en_revision'): ?>
            <section class="card mg-panel"><h3>Decisión administrativa</h3><form class="mg-form-grid" method="post" action="<?= e(app_url('modalidades-grado/solicitudes.php?id=' . $requestId . '&estado=' . rawurlencode($state))) ?>"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id_solicitud" value="<?= $requestId ?>"><label>Observación / motivo (obligatorio al observar o rechazar)<textarea class="form-control" name="observacion" rows="3" maxlength="5000"></textarea></label><div class="mg-actions"><button class="btn btn-outline-primary" name="accion" value="observar">Observar</button><button class="btn btn-outline-danger" name="accion" value="rechazar">Rechazar</button><button class="btn btn-primary" name="accion" value="aprobar" <?= !$currentAcademicComplete || (int) $selectedRequest['modalidad_disponible'] !== 1 || $selectedRequest['estado_usuario'] !== 'activo' ? 'disabled' : '' ?>>Aprobar solicitud</button></div></form></section>
        <?php elseif ($selectedRequest['estado'] === 'aprobada' && !$selectedRequest['id_habilitacion']): ?>
            <section class="card mg-panel"><h3>Habilitación formal</h3><p>La habilitación se registra aparte; no crea una inscripción formal.</p><form method="post" action="<?= e(app_url('modalidades-grado/solicitudes.php?id=' . $requestId . '&estado=' . rawurlencode($state))) ?>"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id_solicitud" value="<?= $requestId ?>"><label>Observación (opcional)<textarea class="form-control" name="observacion" rows="2" maxlength="1000"></textarea></label><button class="btn btn-primary" name="accion" value="habilitar" <?= !$currentAcademicComplete || (int) $selectedRequest['modalidad_disponible'] !== 1 || $selectedRequest['estado_usuario'] !== 'activo' ? 'disabled' : '' ?>>Habilitar proceso</button></form></section>
        <?php elseif ($selectedRequest['id_habilitacion']): ?><section class="card mg-panel"><h3>Habilitación registrada</h3><p><?= e($selectedRequest['habilitado_en']) ?> por <?= e($selectedRequest['habilitado_por'] ?? 'Administración') ?><?= $selectedRequest['observacion_habilitacion'] ? ' — ' . e($selectedRequest['observacion_habilitacion']) : '' ?></p></section><?php endif; ?>

        <section class="card mg-panel"><h3>Historial de auditoría</h3><?php if ($selectedRequest['historial']): ?><div class="table-wrapper"><table><thead><tr><th>Fecha</th><th>Acción</th><th>Estado</th><th>Responsable</th><th>Comentario</th><th>Visibilidad</th><th>Resumen académico</th></tr></thead><tbody><?php foreach ($selectedRequest['historial'] as $event): ?><tr><td><?= e($event['ocurrido_en']) ?></td><td><?= e($event['accion']) ?></td><td><?= e(($event['estado_anterior'] ?? '—') . ' → ' . $event['estado_nuevo']) ?></td><td><?= e($event['actor']) ?></td><td><?= nl2br(e($event['comentario'] ?? '—')) ?></td><td><?= (int) $event['visible_estudiante'] === 1 ? 'Visible al estudiante' : 'Interno' ?></td><td><code><?= e($event['resumen_academico'] ?? '—') ?></code></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p>Sin eventos.</p><?php endif; ?></section>
    <?php endif; ?>
</main>
